import Foundation

/// Pure-logic lookup over the reviewed substitution table resource
/// (`Substitutions/substitutions-v2.json`, generated by
/// `scripts/substitutions/convert.py` from the overhaul branch's reviewed
/// `pairs.json` against the canonical ingredient vocabulary).
///
/// Schema v2 carries canonical ingredient keys, not app ingredient ids: the
/// reviewed table no longer depends on the app's id space, so regeneration
/// cannot silently ship stale ids. Swaps are keyed by `originalKey` /
/// `substituteKey`; mapping canonical keys to app ingredient ids is the
/// platform layer's job (`SubstitutionService` reads the catalog identity
/// bridge). A top-level `compositions` map carries per-key composition facts
/// (full compound closure), denormalized onto each swap's `recheck`.
///
/// The table is reviewed, context-specific data (SPEC overhaul-20261011 §3.5):
/// every pair carries evidence verdicts per functional role and a recheck
/// payload for the substitute's composition. This type loads and screens it;
/// it never invents pairs or upgrades unknown evidence (§3.5: unknown is
/// never upgraded to fit).
public struct SubstitutionDocument: Decodable, Sendable, Equatable {
  public let schemaVersion: String
  public let allergenClasses: [String]
  public let roles: [String]
  public let restrictions: [String: RestrictionScreen]
  public let source: Source
  public let audit: Audit
  public let compositions: [String: CompositionFacts]
  public let swaps: [SubstitutionSwap]

  enum CodingKeys: String, CodingKey {
    case schemaVersion = "schemaVersion"
    case allergenClasses = "allergenClasses"
    case roles = "roles"
    case restrictions = "restrictions"
    case source = "source"
    case audit = "audit"
    case compositions = "compositions"
    case swaps = "swaps"
  }

  public struct Source: Decodable, Sendable, Equatable {
    public let sourceCommit: String
    public let table: String
    public let tableBranch: String?
    public let tableCreated: String?
    public let tableSchemaVersion: String?
    public let vocabulary: String?
    public let converter: String?
  }

  public struct Audit: Decodable, Sendable, Equatable {
    public let referencedIngredients: Int
    public let mappedIngredients: Int
    public let pairsTotal: Int
    public let pairsShipped: Int
    public let pairsDropped: Int
    public let compositionKnownSubstitutes: Int?
    /// Table-side keys that resolved to a canonical key, and those that did
    /// not (fail-closed). Named keys make coverage reviewable in the artifact.
    public let mappedKeys: [String]?
    public let unmappedKeys: [String]?
    public let unmappedIngredients: Int?
  }

  /// Composition facts for one canonical key — the union of the vocabulary's
  /// curated classes and the mapped facts store. `compositionKnown == false`
  /// ships with empty class lists (fail closed).
  public struct CompositionFacts: Decodable, Sendable, Equatable {
    public let compositionKnown: Bool
    public let allergenClasses: [String]
    public let dietClasses: [String]
    public let allergenNote: String?
  }

  /// A restriction's screen: the allergen/diet classes it forbids.
  /// App ids use underscores (`gluten_free`); table names use hyphens
  /// (`gluten-free`) — `SubstitutionTable.canonicalRestriction` normalizes.
  public struct RestrictionScreen: Decodable, Sendable, Equatable {
    public let forbids: [String]
  }
}

/// One reviewed substitution pair, keyed by canonical ingredient keys.
public struct SubstitutionSwap: Decodable, Sendable, Equatable, Identifiable {
  public let pairId: String
  public let originalKey: String
  public let substituteKey: String
  /// Primary functional role of the pair.
  public let role: String
  /// Role fits, primary role first. A fit records its own evidence verdict;
  /// an alternative role never inherits the primary ratio.
  public let fits: [RoleFit]
  /// Roles the swap functionally fails, with the recorded reason.
  public let excludedRoles: [ExcludedRole]
  /// Kitchen-measure ratio for the primary role, when one is recorded.
  public let ratio: Ratio?
  public let preparation: [String]
  /// Plain-language flavour/texture difference. Never promises "no change".
  public let difference: String
  public let sourceIds: [String]
  /// Composition recheck payload for the substitute (denormalized from the
  /// document's `compositions[substituteKey]`).
  public let recheck: Recheck

  public var id: String { pairId }

  enum CodingKeys: String, CodingKey {
    case pairId = "pairId"
    case originalKey = "originalKey"
    case substituteKey = "substituteKey"
    case role = "role"
    case fits = "fits"
    case excludedRoles = "excludedRoles"
    case ratio = "ratio"
    case preparation = "preparation"
    case difference = "difference"
    case sourceIds = "sourceIds"
    case recheck = "recheck"
  }

  public struct RoleFit: Decodable, Sendable, Equatable {
    public let role: String
    /// verified | plausible | unknown | unsupported — evidence mapping from
    /// the table's ContextRules; `unknown` is never upgraded to fit.
    public let verdict: String
    public let functionStatus: String
    public let ratio: Ratio?
    /// Restrictions this role's fit is conditionally refused for.
    public let conditionalFor: [String]
  }

  public struct ExcludedRole: Decodable, Sendable, Equatable {
    public let role: String
    public let kind: String
    public let why: String?
  }

  public struct Ratio: Decodable, Sendable, Equatable {
    public let value: Double
    /// Kitchen statement the value is expressed in (`weight`, `tbsp-per-tbsp`,
    /// `quarter-cup-per-egg`, ...). Only mass statements scale arithmetically
    /// in grams; the app states the kitchen measure for the others.
    public let basis: String
    public let status: String
    public let note: String?
    public let scales: Bool
  }

  public struct Recheck: Decodable, Sendable, Equatable {
    /// False fails closed: the composition cannot be settled, so the swap is
    /// never offered under an active restriction — it surfaces ask-the-user.
    public let compositionKnown: Bool
    /// Full compound closure of the substitute (soy sauce carries soy AND
    /// gluten), from the canonical composition facts store.
    public let allergenClasses: [String]
    /// Diet-extension classes the diet screens use (flesh_fish, ...).
    public let dietClasses: [String]
    public let allergenNote: String?
  }
}

/// The outcome of screening one swap's substitute composition for a set of
/// active eater restrictions.
public enum CompositionScreen: Sendable, Equatable {
  /// No active restriction forbids a component the substitute carries.
  case allowed
  /// The composition cannot be settled — ask the user (check the label).
  case askUser
  /// A restriction forbids a component the substitute actually carries.
  case refused(offending: [String])
}

/// Lookup and per-eater screening over a loaded document, indexed by
/// canonical ingredient key.
public struct SubstitutionTable: Sendable {
  public let document: SubstitutionDocument
  private let byOriginalKey: [String: [SubstitutionSwap]]

  public init(document: SubstitutionDocument) {
    self.document = document
    var index: [String: [SubstitutionSwap]] = [:]
    for swap in document.swaps {
      index[swap.originalKey, default: []].append(swap)
    }
    // Deterministic order everywhere.
    for key in index.keys {
      index[key]?.sort { $0.pairId < $1.pairId }
    }
    self.byOriginalKey = index
  }

  /// Decodes the document emitted by `scripts/substitutions/convert.py`.
  /// Anything that is not schema 2 fails the load — a stale v1 resource must
  /// leave the service empty, not half-work.
  public init(data: Data) throws {
    let document = try JSONDecoder().decode(SubstitutionDocument.self, from: data)
    guard document.schemaVersion.hasPrefix("2.") else {
      throw DecodingError.dataCorrupted(
        DecodingError.Context(
          codingPath: [],
          debugDescription: "unsupported substitutions schemaVersion: \(document.schemaVersion)"))
    }
    self.init(document: document)
  }

  public var schemaVersion: String { document.schemaVersion }

  /// All reviewed swaps for a canonical original ingredient, unfiltered.
  public func swaps(forCanonical originalKey: String) -> [SubstitutionSwap] {
    byOriginalKey[originalKey] ?? []
  }

  public func hasSwaps(forCanonical originalKey: String) -> Bool {
    !(byOriginalKey[originalKey] ?? []).isEmpty
  }

  /// Canonical keys the table actually offers swaps from.
  public var originalKeys: [String] {
    byOriginalKey.keys.sorted()
  }

  /// Maps app restriction ids to the table's canonical restriction names.
  /// Unknown ids (`keto`, `low_carb`) are returned as-is and simply screen
  /// nothing: the reviewed table defines no forbids for them, so they can
  /// neither allow nor refuse a swap here.
  public static func canonicalRestriction(_ appRestriction: String) -> String {
    let normalized = appRestriction.replacingOccurrences(of: "_", with: "-").lowercased()
    // The table's 13 restrictions; unknown ids pass through unchanged.
    return normalized
  }

  /// Screens the substitute's composition for one eater's active restrictions.
  ///
  /// - `compositionKnown == false` fails closed to `.askUser` under any active
  ///   restriction (the affected restriction can never offer the swap).
  /// - A substitute key missing from `compositions` screens as unknown too
  ///   (the converter guarantees coverage; a hand-edited resource must not
  ///   open a refusal hole).
  /// - Otherwise any forbidden class the substitute carries refuses the swap,
  ///   naming the offending classes (compound closure included).
  public func screen(
    _ swap: SubstitutionSwap,
    restrictions: Set<String>
  ) -> CompositionScreen {
    let active = restrictions.map(Self.canonicalRestriction)
    guard !active.isEmpty else { return .allowed }
    guard swap.recheck.compositionKnown else { return .askUser }

    let carried = Set(swap.recheck.allergenClasses).union(swap.recheck.dietClasses)
    var offending = Set<String>()
    for restriction in active {
      guard let screen = document.restrictions[restriction] else { continue }
      offending.formUnion(carried.intersection(screen.forbids))
    }
    if offending.isEmpty { return .allowed }
    return .refused(offending: offending.sorted())
  }

  /// Swaps for a canonical ingredient that screen clean for every active
  /// restriction. Swaps with unknown composition are dropped while
  /// restrictions are active (fail closed — the caller surfaces ask-the-user
  /// states separately via `screenedSwaps`).
  public func allowedSwaps(
    forCanonical originalKey: String,
    restrictions: Set<String>
  ) -> [SubstitutionSwap] {
    swaps(forCanonical: originalKey).filter { swap in
      if case .allowed = screen(swap, restrictions: restrictions) { return true }
      return false
    }
  }

  /// Every swap with its screen outcome, so callers can surface ask-the-user
  /// states instead of silently dropping them.
  public func screenedSwaps(
    forCanonical originalKey: String,
    restrictions: Set<String>
  ) -> [(swap: SubstitutionSwap, screen: CompositionScreen)] {
    swaps(forCanonical: originalKey).map { ($0, screen($0, restrictions: restrictions)) }
  }

  /// The verdict of the primary role fit — the evidence strength the table
  /// recorded for the pair's main use.
  public static func primaryVerdict(of swap: SubstitutionSwap) -> String? {
    swap.fits.first { $0.role == swap.role }?.verdict
      ?? swap.fits.first?.verdict
  }
}
